bool Audios::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{

    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }

    if(pJson.isMember("title"))
    {
        if(!validJsonOfField(1, "title", pJson["title"], err, true))
            return false;
    }

    else
    {
        err="The title column cannot be null";
        return false;
    }

    if(pJson.isMember("series_name"))
    {
        if(!validJsonOfField(2, "series_name", pJson["series_name"], err, true))
            return false;
    }

    if(pJson.isMember("description"))
    {
        if(!validJsonOfField(3, "description", pJson["description"], err, true))
            return false;
    }

    if(pJson.isMember("file_path"))
    {
        if(!validJsonOfField(4, "file_path", pJson["file_path"], err, true))
            return false;
    }

    else
    {
        err="The file_path column cannot be null";
        return false;
    }

    if(pJson.isMember("duration_seconds"))
    {
        if(!validJsonOfField(5, "duration_seconds", pJson["duration_seconds"], err, true))
            return false;
    }

    if(pJson.isMember("status"))
    {
        if(!validJsonOfField(6, "status", pJson["status"], err, true))
            return false;
    }

    if(pJson.isMember("plays"))
    {
        if(!validJsonOfField(7, "plays", pJson["plays"], err, true))
            return false;
    }

    if(pJson.isMember("likes"))
    {
        if(!validJsonOfField(8, "likes", pJson["likes"], err, true))
            return false;
    }

    if(pJson.isMember("created_by"))
    {
        if(!validJsonOfField(9, "created_by", pJson["created_by"], err, true))
            return false;
    }

    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(10, "created_at", pJson["created_at"], err, true))
            return false;
    }

    return true;
}
